function cleanState(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('状态格式不正确');const s=initial();for(const k of ['mode','group','axis','wheel','flow','paint','task']){const options={mode:modes.map(m=>m.id),group:['all',...groups.map(g=>g.id)],axis:['x','y','z'],wheel:['both','front','rear'],flow:['air','power'],paint:Object.keys(colour),task:tasks.map(t=>t.id)};if(raw[k]!==undefined){if(!options[k].includes(raw[k]))throw Error('无效字段：'+k);s[k]=raw[k];}}for(const [k,a,b]of [['progress',0,1],['step',0,6],['opacity',0,1],['angle',0,360],['phase',0,1],['lengthMM',0,10000],['inspection',0,3]]){if(raw[k]!==undefined){if(typeof raw[k]!=='number'||!Number.isFinite(raw[k]))throw Error('无效数值：'+k);s[k]=clamp(raw[k],a,b);}}s.step=Math.round(s.step);s.inspection=Math.round(s.inspection);for(const k of ['flip','hideOthers','luggage','screen','reduced'])if(raw[k]!==undefined){if(typeof raw[k]!=='boolean')throw Error('无效开关：'+k);s[k]=raw[k];}s.mesh=expectedNames.includes(raw.mesh)?raw.mesh:'';s.note=typeof raw.note==='string'?raw.note.slice(0,5000):'';return s;}
